 3","group":"Pasca Lebaran · Gladi & tapering","kind":"day","date":"2027-03-18","end":"","label":"TO-9","title":"Gladi: full simulation 12 jam, hari 2 (6 jam)","target":"Skor ≥ 80","hours":6.5,"to":"to9"},{"id":"d20270319","tab":"Fase 3","group":"Pasca Lebaran · Gladi & tapering","kind":"day","date":"2027-03-19","end":"","label":"M12","title":"Bedah TO-9; time plan final; daftar 'jangan lupa' pribadi","target":"Time plan final","hours":6.5,"to":""},{"id":"we13","tab":"Fase 3","group":"Pasca Lebaran · Gladi & tapering","kind":"weekend","date":"2027-03-20","end":"2027-03-21","label":"Mandiri","title":"Istirahat; angka teknis ringan\nBaca time plan final 2 kali","target":"Siap tapering","hours":0,"to":""},{"id":"d20270322","tab":"Fase 3","group":"Pasca Lebaran · Gladi & tapering","kind":"day","date":"2027-03-22","end":"","label":"M12","title":"Tapering: drill ringan aspek terlemah, kecepatan aspek bernilai besar","target":"Mutu stabil","hours":4,"to":"","note":"Geser hari tapering bila tanggal lomba sudah pasti: selesai 1–2 hari sebelum lomba"},{"id":"d20270323","tab":"Fase 3","group":"Pasca Lebaran · Gladi & tapering","kind":"day","date":"2027-03-23","end":"","label":"M12","title":"Latihan ringan 3 jam; cek alat final, packing, cek laptop sekali lagi","target":"Checklist alat final","hours":3,"to":""},{"id":"d20270324","tab":"Fase 3","group":"Pasca Lebaran · Gladi & tapering","kind":"day","date":"2027-03-24","end":"","label":"–","title":"Istirahat aktif; logistik, perjalanan, briefing aturan lomba","target":"Siap berlomba","hours":2,"to":""}],"gates":[{"id":"G1","ph":"F1","items":["Kuis angka teknis ≥ 90%","Time plan gambar baru ≤ 20 menit","Nol pelanggaran K3 berat"],"phName":"Diagnostik & Fondasi"},{"id":"G2","ph":"F2","items":["Marking out layout baru","Semua titik masuk ±2 mm","Selesai ≤ 90 menit"],"phName":"Hand Skill & Marking Out"},{"id":"G3","ph":"F3","items":["Gap sambungan < 1 mm","Radius pipa ≥ 6 × OD","Containment + wiring ≤ 5 jam"],"phName":"Containment & Wiring"},{"id":"G4","ph":"F4","items":["DOL, forward-reverse, star-delta jalan di attempt pertama","Program smart relay ≤ 60 menit"],"phName":"Motor Control & Smart Relay"},{"id":"G5","ph":"F5","items":["Skenario KNX baru ≤ 90 menit","Switching, dimming, shutter jalan","Group address rapi dan konsisten"],"phName":"KNX Building Automation"},{"id":"G6","ph":"F6","items":["Full testing ≤ 45 menit","Test sheet tanpa kolom bolong","≥ 7 dari 8 fault ketemu"],"phName":"Testing, Fault Finding & Maintenance"},{"id":"G7","ph":"F7","items":["Full simulation 12 jam dengan juri, bising, penonton","Skor total ≥ 80","Semua fungsi jalan saat demo pertama"],"phName":"Integrasi & Full Simulation"}],"angka":[["Toleransi semua ukuran?","±2 mm, diukur dari datum"],["Radius minimum bending pipa logam dan PVC?","6 × OD"],["Radius minimum bending kabel?","3 × D"],["Tahanan isolasi minimum dan tegangan ujinya?","1 MΩ pada 500 V DC"],["Tahanan pembumian maksimum?","0,5 Ω"],["Gap maksimum sambungan trunking dan tutupnya?","< 1 mm"],["Urutan fasa socket 3 fasa?","Searah jarum jam (CW); fasa di kiri untuk socket 1 fasa"],["Lama test project lomba?","12 jam, Modul A + B, dua hari, tanpa tambahan waktu"],["Rata-rata nilai per menit di lomba?","1 poin ≈ 7 menit"],["Komposisi judgement dan measurement?","Judgement 11 poin, Measurement 89 poin"],["Selisih maksimal nilai antar juri judgement?","1"],["Power supply bus KNX yang dipakai?","640 mA, bus dipisah dari kabel daya"],["Smart relay yang dipakai?","LOGO! 230RCE"],["Sebut 4 alat listrik yang dilarang di arena","Gerinda tangan, jig saw, circular saw, mal/jig pemotong atau pembengkok"],["Clearance double set lewat rintangan?","20–30 mm"]],"selection":{"full":["to5","to7","to8"],"trendFrom":"to5","trendTo":"to8","w":{"full":50,"trend":20,"gate":20,"kons":10},"target":80},"docUrl":"https://claude.ai/artifact/8XZxBQ77xjjhsnAwCEEBLD","jobsheetUrl":"https://claude.ai/artifact/MBnUAWae91WABVv4EsVSNN","istilah":[{"g":"A. Lomba dan penilaian","t":"LKS","a":"Lomba Kompetensi Siswa SMK; bidang kita *Electrical Installations* (EI)."},{"g":"A. Lomba dan penilaian","t":"Test project","a":"Soal lomba: gambar, deskripsi fungsi, dan daftar bahan. Dikerjakan 12 jam."},{"g":"A. Lomba dan penilaian","t":"Modul A / Modul B","a":"Bagian test project. Umumnya A = pemasangan (marking out, containment, wiring), B = kendali, smart relay, KNX, pengujian."},{"g":"A. Lomba dan penilaian","t":"Marking scheme","a":"Daftar semua yang dinilai beserta poinnya (total 100 poin)."},{"g":"A. Lomba dan penilaian","t":"Kriteria","a":"Kelompok besar penilaian, misalnya \"Safety & Commissioning\" atau \"Instalasi Jalur Kabel\". Di TIS ada 7 kriteria."},{"g":"A. Lomba dan penilaian","t":"Aspek","a":"Butir penilaian di dalam kriteria, misalnya \"1.3 Semua kerja dead\"."},{"g":"A. Lomba dan penilaian","t":"Measurement (M)","a":"Aspek yang dinilai pasti: terpenuhi (Y) atau tidak (N). Diisi Y/N."},{"g":"A. Lomba dan penilaian","t":"C (count)","a":"Aspek yang dinilai dengan hitungan, misalnya jumlah titik ukur yang masuk toleransi (0–10)."},{"g":"A. Lomba dan penilaian","t":"Judgement (J)","a":"Aspek yang dinilai mata juri dengan skala 0–3, misalnya kerapian. Total 11 poin."},{"g":"A. Lomba dan penilaian","t":"J1 / J2 / J3","a":"Nilai dari Juri 1, Juri 2, Juri 3 untuk aspek J. Dirata-rata."},{"g":"A. Lomba dan penilaian","t":"Selisih maks 1","a":"Nilai antarjuri untuk aspek J tidak boleh berbeda lebih dari 1; bila lebih, juri berdiskusi dulu."},{"g":"A. Lomba dan penilaian","t":"Skala 0–3 (J)","a":"0 di bawah standar · 1 standar industri · 2 di atas standar · 3 melebihi ekspektasi (mulus dari jarak 30 cm)."},{"g":"A. Lomba dan penilaian","t":"Skala 100","a":"Nilai TO dikonversi ke 100 supaya TO yang hanya menguji sebagian kriteria tetap bisa dibandingkan."},{"g":"A. Lomba dan penilaian","t":"Bahan tambahan","a":"Bahan yang diminta di luar jatah. Potongan −1 poin per item."},{"g":"A. Lomba dan penilaian","t":"Pelanggaran K3 berat","a":"Misalnya bekerja dalam keadaan bertegangan. Nilai TO menjadi 0."},{"g":"A. Lomba dan penilaian","t":"Attempt pertama","a":"Fungsi dinilai saat pertama kali diberi tegangan; perbaikan sesudahnya tidak menaikkan nilai."},{"g":"A. Lomba dan penilaian","t":"Demo fungsi","a":"Peserta menunjukkan cara kerja rangkaian ke juri."},{"g":"A. Lomba dan penilaian","t":"Commissioning","a":"Rangkaian pengujian dan penyerahan instalasi sampai siap dipakai."},{"g":"A. Lomba dan penilaian","t":"CIS","a":"Sistem penilaian WorldSkills; format lembar di TIS mengikuti gayanya."},{"g":"A. Lomba dan penilaian","t":"Mark Summary Form","a":"Lembar ringkasan nilai per kriteria."},{"g":"A. Lomba dan penilaian","t":"Marking Form","a":"Lembar nilai rinci per aspek."},{"g":"B. Program pelatihan","t":"Fase 1 / 2 / 3","a":"Tahap program: Fase 1 (19 Nov–18 Des), Fase 2 (4 Jan–4 Feb), Fase 3 pemantapan peserta terpilih (8 Feb–24 Mar)."},{"g":"B. Program pelatihan","t":"F1–F8","a":"Fase menurut silabus, dari diagnostik sampai peaking & tapering."},{"g":"B. Program pelatihan","t":"M1–M12","a":"12 modul silabus, misalnya M3 marking out, M7 smart relay, M8 KNX."},{"g":"B. Program pelatihan","t":"JS-xx","a":"Nomor jobsheet harian."},{"g":"B. Program pelatihan","t":"TM-x","a":"Tugas mandiri akhir pekan atau libur."},{"g":"B. Program pelatihan","t":"TO","a":"Try out: simulasi lomba yang dinilai dengan marking scheme. TO-1 s.d. TO-9."},{"g":"B. Program pelatihan","t":"Diagnostik / baseline","a":"TO-1: mengukur kemampuan awal sebelum dilatih."},{"g":"B. Program pelatihan","t":"Full simulation","a":"TO penuh 12 jam, semua kriteria (TO-5, TO-7, TO-8, TO-9)."},{"g":"B. Program pelatihan","t":"Gladi","a":"Simulasi terakhir sebelum lomba (TO-9)."},{"g":"B. Program pelatihan","t":"Gate test (G1–G7)","a":"Syarat lulus tiap tahap. Lulus gate = boleh naik ke tahap berikutnya."},{"g":"B. Program pelatihan","t":"Drill","a":"Latihan berulang satu keterampilan dengan target angka."},{"g":"B. Program pelatihan","t":"Blok","a":"Latihan berwaktu panjang yang menggabungkan beberapa pekerjaan (misalnya blok 3 jam)."},{"g":"B. Program pelatihan","t":"Time plan","a":"Rencana urutan kerja dan waktu per bagian."},{"g":"B. Program pelatihan","t":"Checkpoint","a":"Titik cek di time plan (misalnya \"jam ke-3: semua trunking terpasang\")."},{"g":"B. Program pelatihan","t":"Bedah TO","a":"Membahas hasil TO per aspek untuk menentukan drill berikutnya."},{"g":"B. Program pelatihan","t":"Aspek terlemah","a":"Aspek yang paling banyak kehilangan nilai."},{"g":"B. Program pelatihan","t":"Simulasi bertekanan","a":"Latihan dengan gangguan (bising, penonton) agar terbiasa dengan suasana arena."},{"g":"B. Program pelatihan","t":"Surprise task","a":"Tugas mendadak di tengah pekerjaan, misalnya mengganti komponen."},{"g":"B. Program pelatihan","t":"Peaking","a":"Membuat performa memuncak tepat saat lomba."},{"g":"B. Program pelatihan","t":"Tapering","a":"Mengurangi beban latihan menjelang lomba agar tubuh segar."},{"g":"B. Program pelatihan","t":"Indeks seleksi","a":"Angka gabungan untuk memilih 1 peserta: full simulation 50%, tren 20%, gate 20%, konsistensi 10%."},{"g":"B. Program pelatihan","t":"Tren","a":"Selisih skor TO-8 terhadap TO-5."},{"g":"B. Program pelatihan","t":"Konsistensi","a":"Dihitung dari pelanggaran K3 dan bahan tambahan."},{"g":"B. Program pelatihan","t":"Angka teknis","a":"Angka penting yang wajib dihafal (lihat tab Materi angka teknis)."},{"g":"C. Pemasangan dan containment","t":"Datum","a":"Garis acuan di gambar; semua ukuran diambil dari sini."},{"g":"C. Pemasangan dan containment","t":"Toleransi ±2 mm","a":"Batas meleset setiap titik ukur."},{"g":"C. Pemasangan dan containment","t":"Marking out","a":"Menandai posisi komponen dan jalur dari datum."},{"g":"C. Pemasangan dan containment","t":"Kerataan","a":"Komponen lurus horizontal dan vertikal; dicek dengan waterpass dua arah."},{"g":"C. Pemasangan dan containment","t":"Containment","a":"Semua jalur pelindung kabel: trunking, conduit, slotted duct."},{"g":"C. Pemasangan dan containment","t":"Trunking","a":"Saluran kabel berpenutup."},{"g":"C. Pemasangan dan containment","t":"Mitre 45°","a":"Sambungan sudut trunking dengan potongan miring 45°."},{"g":"C. Pemasangan dan containment","t":"Sambungan T","a":"Percabangan trunking."},{"g":"C. Pemasangan dan containment","t":"Gap","a":"Celah sambungan; harus < 1 mm."},{"g":"C. Pemasangan dan containment","t":"Conduit","a":"Pipa pelindung kabel, logam atau PVC."},{"g":"C. Pemasangan dan containment","t":"Bending","a":"Membengkokkan pipa."},{"g":"C. Pemasangan dan containment","t":"OD","a":"Outside diameter, diameter luar pipa atau kabel."},{"g":"C. Pemasangan dan containment","t":"Radius 6 × OD","a":"Jari-jari bengkokan minimum pipa. Kabel: 3 × D."},{"g":"C. Pemasangan dan containment","t":"Set / offset","a":"Bengkokan ganda untuk menggeser jalur pipa."},{"g":"C. Pemasangan dan containment","t":"Double set","a":"Dua set untuk melewati rintangan."},{"g":"C. Pemasangan dan containment","t":"Clearance","a":"Jarak bebas pipa dari rintangan: 20–30 mm."},{"g":"C. Pemasangan dan containment","t":"Saddle / klem","a":"Penjepit pipa atau kabel ke papan."},{"g":"C. Pemasangan dan containment","t":"Hole saw","a":"Mata bor bulat untuk lubang komponen."},{"g":"C. Pemasangan dan containment","t":"Deburring","a":"Membersihkan bekas potongan atau lubang yang tajam."},{"g":"C. Pemasangan dan containment","t":"Base plate","a":"Pelat dasar panel."},{"g":"C. Pemasangan dan containment","t":"DIN rail","a":"Rel standar tempat MCB, kontaktor, dan terminal dipasang."},{"g":"C. Pemasangan dan containment","t":"Slotted duct","a":"Saluran kabel berlubang di dalam panel."},{"g":"C. Pemasangan dan containment","t":"Looming","a":"Merapikan kabel menjadi berkas yang rapi."},{"g":"C. Pemasangan dan containment","t":"Labeling","a":"Memberi label kabel dan komponen sesuai diagram."},{"g":"C. Pemasangan dan containment","t":"Ferrule","a":"Selongsong logam di ujung kabel serabut sebelum masuk terminal."},{"g":"C. Pemasangan dan containment","t":"Skun","a":"Terminal kabel berbentuk cincin atau garpu."},{"g":"C. Pemasangan dan containment","t":"Crimp","a":"Menjepit ferrule atau skun dengan tang crimping."},{"g":"C. Pemasangan dan containment","t":"Pull test","a":"Uji tarik untuk memastikan crimp dan terminasi kuat."},{"g":"C. Pemasangan dan containment","t":"Terminasi","a":"Sambungan ujung kabel ke terminal; tidak boleh ada tembaga terlihat."},{"g":"C. Pemasangan dan containment","t":"Kode warna","a":"L1 coklat, L2 hitam, L3 abu-abu, N biru, PE hijau-kuning."},{"g":"D. Kendali, smart relay, dan KNX","t":"Kontaktor","a":"Saklar elektromagnet untuk menghubungkan beban (motor)."},{"g":"D. Kendali, smart relay, dan KNX","t":"Kontak NO / NC","a":"Normally open (terbuka saat tidak aktif) / normally closed (tertutup saat tidak aktif)."},{"g":"D. Kendali, smart relay, dan KNX","t":"Kontak bantu","a":"Kontak tambahan kontaktor untuk rangkaian kendali."},{"g":"D. Kendali, smart relay, dan KNX","t":"Latching / pengunci","a":"Rangkaian yang membuat kontaktor tetap masuk setelah tombol start dilepas."},{"g":"D. Kendali, smart relay, dan KNX","t":"TOR","a":"Thermal overload relay: proteksi motor dari beban lebih."},{"g":"D. Kendali, smart relay, dan KNX","t":"DOL","a":"Direct on line: motor dihidupkan langsung."},{"g":"D. Kendali, smart relay, dan KNX","t":"Forward-reverse","a":"Rangkaian putar kanan-kiri motor."},{"g":"D. Kendali, smart relay, dan KNX","t":"Interlock","a":"Pengaman agar dua kontaktor tidak masuk bersamaan."},{"g":"D. Kendali, smart relay, dan KNX","t":"Star-delta","a":"Start motor bintang lalu pindah ke segitiga untuk mengurangi arus start."},{"g":"D. Kendali, smart relay, dan KNX","t":"Timer (TDR)","a":"Time delay relay: penunda waktu."},{"g":"D. Kendali, smart relay, dan KNX","t":"E-stop","a":"Tombol berhenti darurat."},{"g":"D. Kendali, smart relay, dan KNX","t":"Selector","a":"Saklar pilih (misalnya manual/otomatis)."},{"g":"D. Kendali, smart relay, dan KNX","t":"Smart relay","a":"Relay yang bisa diprogram; di lomba memakai LOGO! 230RCE."},{"g":"D. Kendali, smart relay, dan KNX","t":"LOGO! Soft Comfort","a":"Software untuk memprogram LOGO!."},{"g":"D. Kendali, smart relay, dan KNX","t":"FBD","a":"Function block diagram: cara memprogram dengan blok."},{"g":"D. Kendali, smart relay, dan KNX","t":"On-delay / off-delay","a":"Timer tunda menyala / tunda mati."},{"g":"D. Kendali, smart relay, dan KNX","t":"Stairway (lampu tangga)","a":"Timer yang menyala sekian waktu lalu mati sendiri."},{"g":"D. Kendali, smart relay, dan KNX","t":"Counter","a":"Penghitung jumlah pulsa."},{"g":"D. Kendali, smart relay, dan KNX","t":"Web server / IP","a":"Fitur LOGO! untuk diakses lewat jaringan; alamat IP harus diatur."},{"g":"D. Kendali, smart relay, dan KNX","t":"Backup micro SD","a":"Menyimpan program LOGO! di kartu micro SD."},{"g":"D. Kendali, smart relay, dan KNX","t":"KNX","a":"Standar otomasi gedung dengan kabel bus."},{"g":"D. Kendali, smart relay, dan KNX","t":"ETS","a":"Software untuk memprogram perangkat KNX."},{"g":"D. Kendali, smart relay, dan KNX","t":"PSU 640 mA","a":"Catu daya bus KNX."},{"g":"D. Kendali, smart relay, dan KNX","t":"Physical address","a":"Alamat unik setiap perangkat KNX."},{"g":"D. Kendali, smart relay, dan KNX","t":"Group address (GA)","a":"Alamat fungsi yang menghubungkan tombol dengan aktuator."},{"g":"D. Kendali, smart relay, dan KNX","t":"Aktuator","a":"Perangkat KNX penggerak beban: switching, dimmer, shutter."},{"g":"D. Kendali, smart relay, dan KNX","t":"Binary input","a":"Perangkat KNX yang membaca kontak biasa."},{"g":"D. Kendali, smart relay, dan KNX","t":"Push button 4 gang","a":"Tombol KNX dengan 4 tombol."},{"g":"D. Kendali, smart relay, dan KNX","t":"Group monitor","a":"Fitur ETS untuk melihat telegram dan mencari error."},{"g":"D. Kendali, smart relay, dan KNX","t":"Scene / central","a":"Satu perintah untuk banyak fungsi sekaligus (misalnya \"semua lampu mati\")."},{"g":"E. Pengujian, fault finding, dan K3","t":"K3","a":"Keselamatan dan kesehatan kerja."},{"g":"E. Pengujian, fault finding, dan K3","t":"PPE","a":"Personal protective equipment: kacamata, sepatu, sarung tangan, ear plug."},{"g":"E. Pengujian, fault finding, dan K3","t":"Dead / live","a":"Tanpa tegangan / bertegangan. Semua pekerjaan harus dalam keadaan dead."},{"g":"E. Pengujian, fault finding, dan K3","t":"LOTO","a":"Lock out tag out: gembok dan label agar sumber tidak dinyalakan orang lain."},{"g":"E. Pengujian, fault finding, dan K3","t":"Energisasi","a":"Memberi tegangan ke rangkaian; hanya setelah diizinkan pembina/juri."},{"g":"E. Pengujian, fault finding, dan K3","t":"Inspeksi visual","a":"Pemeriksaan mata sebelum pengukuran."},{"g":"E. Pengujian, fault finding, dan K3","t":"Zeroing","a":"Me-nol-kan alat ukur tahanan rendah sebelum mengukur."},{"g":"E. Pengujian, fault finding, dan K3","t":"Continuity","a":"Uji sambungan tidak putus, termasuk penghantar PE."},{"g":"E. Pengujian, fault finding, dan K3","t":"IR (insulation resistance)","a":"Tahanan isolasi, diuji 500 V DC; minimal 1 MΩ."},{"g":"E. Pengujian, fault finding, dan K3","t":"Pembumian","a":"Tahanan penghantar proteksi; maksimal 0,5 Ω."},{"g":"E. Pengujian, fault finding, dan K3","t":"Polarity","a":"Fasa dan netral terpasang di tempat yang benar."},{"g":"E. Pengujian, fault finding, dan K3","t":"Urutan fasa","a":"L1–L2–L3 searah jarum jam pada socket 3 fasa."},{"g":"E. Pengujian, fault finding, dan K3","t":"Test sheet","a":"Lembar hasil pengujian; tidak boleh ada kolom kosong."},{"g":"E. Pengujian, fault finding, dan K3","t":"MCB","a":"Pemutus arus mini untuk proteksi beban lebih dan hubung singkat."},{"g":"E. Pengujian, fault finding, dan K3","t":"ELCB / RCD","a":"Pemutus arus bocor tanah."},{"g":"E. Pengujian, fault finding, dan K3","t":"Fault finding","a":"Mencari kerusakan pada rangkaian."},{"g":"E. Pengujian, fault finding, dan K3","t":"Fault rig","a":"Papan latihan berisi kerusakan yang sengaja dipasang."},{"g":"E. Pengujian, fault finding, dan K3","t":"Half-split","a":"Cara mencari fault dengan membagi rangkaian menjadi dua bagian berulang-ulang."},{"g":"E. Pengujian, fault finding, dan K3","t":"Open circuit","a":"Rangkaian putus."},{"g":"E. Pengujian, fault finding, dan K3","t":"Short circuit","a":"Hubung singkat."},{"g":"E. Pengujian, fault finding, dan K3","t":"Maintenance","a":"Perawatan atau penggantian komponen tanpa merusak instalasi lain."},{"g":"F. Aplikasi TIS","t":"TIS","a":"Training Information System: aplikasi pemantau latihan."},{"g":"F. Aplikasi TIS","t":"Musim","a":"Satu periode program (misalnya LKS EI 2026–2027)."},{"g":"F. Aplikasi TIS","t":"Admin / Juri / Pengamat","a":"Peran pengguna: semua menu / mengisi nilai, jurnal, log / hanya melihat."},{"g":"F. Aplikasi TIS","t":"Beranda","a":"Halaman awal: jadwal hari ini, kuis angka teknis, TO berikutnya."},{"g":"F. Aplikasi TIS","t":"Jadwal · Tuntas","a":"Daftar latihan harian; dicentang bila target hari itu tercapai."},{"g":"F. Aplikasi TIS","t":"Assessment","a":"Tempat mengisi nilai TO per aspek, catatan juri, dan foto."},{"g":"F. Aplikasi TIS","t":"Results","a":"Grafik dan tabel hasil semua TO serta indeks seleksi."},{"g":"F. Aplikasi TIS","t":"Gate Test","a":"Daftar syarat G1–G7 yang dicentang saat terbukti."},{"g":"F. Aplikasi TIS","t":"Reports","a":"Lembar cetak: laporan hasil TO, Mark Summary, Marking Form."},{"g":"F. Aplikasi TIS","t":"Jurnal","a":"Catatan angka latihan per siswa per drill."},{"g":"F. Aplikasi TIS","t":"Log Harian","a":"Laporan kegiatan harian asisten."},{"g":"F. Aplikasi TIS","t":"Aktivitas otomatis","a":"Catatan otomatis siapa mengisi apa dan jam berapa."},{"g":"F. Aplikasi TIS","t":"MARKS OPEN / LOCKED","a":"Nilai TO masih bisa diubah / sudah dikunci admin."},{"g":"F. Aplikasi TIS","t":"COMPLETE / PARTIAL","a":"Semua aspek TO sudah dinilai / belum semua."},{"g":"F. Aplikasi TIS","t":"✓ / ✗","a":"Tersimpan / gagal tersimpan (cek internet, isi ulang)."},{"g":"F. Aplikasi TIS","t":"OFFLINE","a":"Internet terputus."},{"g":"F. Aplikasi TIS","t":"SUPABASE LIVE","a":"Aplikasi tersambung ke database online."},{"g":"F. Aplikasi TIS","t":"Mode demo","a":"Aplikasi berjalan tanpa database (data hanya di browser itu)."},{"g":"F. Aplikasi TIS","t":"Impor Excel","a":"Mengganti jadwal, TO, scheme, atau gate dari berkas Excel."},{"g":"F. Aplikasi TIS","t":"Backup","a":"Cadangan seluruh data musim, disarankan diunduh sebulan sekali."},{"g":"G. Marking scheme standar EI","t":"Sub-kriteria (A1, B2, C1 …)","a":"Kelompok aspek di dalam satu kriteria. Contoh: kriteria C dibagi menjadi C1 Measurements dan C2 Plumb/Level. Kode aspek di TIS ditulis C1.3, artinya aspek ke-3 di C1."},{"g":"G. Marking scheme standar EI","t":"WSSS","a":"WorldSkills Standards Specification. Tujuh bagian kompetensi beserta bobotnya, misalnya Installation 35% dan Testing 25%. Marking scheme disusun mengikuti bobot ini."},{"g":"G. Marking scheme standar EI","t":"Day of marking","a":"Hari (modul) ketika aspek dinilai. Di lomba, aspek tertentu hanya bisa dinilai pada hari pekerjaan itu selesai."},{"g":"G. Marking scheme standar EI","t":"Experts / marking team","a":"Tim juri penilai. Banyak aspek mensyaratkan \"confirmed by at least 2 Experts\", artinya keputusan harus disetujui minimal 2 juri."},{"g":"G. Marking scheme standar EI","t":"Visual check","a":"Penilaian dengan melihat langsung, tanpa alat ukur. Misalnya komponen sudah di lokasi yang benar sesuai gambar."},{"g":"G. Marking scheme standar EI","t":"Electrical supply requested","a":"Saat peserta meminta listrik dinyalakan. Pada saat itu instalasi harus sudah lengkap (semua alat dan tutup terpasang) dan aman (semua kabel tersambung)."},{"g":"G. Marking scheme standar EI","t":"Power-up","a":"Saat rangkaian pertama kali diberi tegangan. Praktik kerja yang tidak aman yang terlihat oleh 2 juri membuat aspek ini bernilai 0."},{"g":"G. Marking scheme standar EI","t":"Earth fault","a":"Gangguan ke tanah: penghantar fasa menyentuh bagian yang dibumikan. Short circuit atau earth fault saat power-up atau commissioning membuat aspek bernilai 0."},{"g":"G. Marking scheme standar EI","t":"Function chart","a":"Lembar tabel fungsi yang diisi peserta sesuai fungsi nyata instalasinya. Dinilai saat commissioning."},{"g":"G. Marking scheme standar EI","t":"Safe work practices","a":"Cara kerja aman selama power-up, commissioning, dan programming, misalnya memakai alat ukur yang benar dan tidak menyentuh bagian bertegangan."},{"g":"G. Marking scheme standar EI","t":"Circuit design","a":"Pemilihan ukuran dan jenis kabel serta kode warna sesuai instruksi. Contoh: 1,5 mm² solid untuk POS ke A1, dan 1,5 mm² twisted (serabut) untuk rangkaian kontrol."},{"g":"G. Marking scheme standar EI","t":"Solid / twisted","a":"Solid: kabel inti tunggal (kaku), misalnya NYA atau NYM. Twisted/stranded: kabel inti serabut (lentur), misalnya NYAF, yang biasa dipakai di panel kontrol."},{"g":"G. Marking scheme standar EI","t":"Colour codes L1/L2/L3","a":"Kode warna penghantar fasa sesuai instruksi soal, juga untuk N, PE, dan rangkaian kontrol. Satu kesalahan warna membuat aspek ini bernilai 0."},{"g":"G. Marking scheme standar EI","t":"Manual function","a":"Uji fungsi dengan mengoperasikan perangkat secara manual sebelum diprogram. Contohnya menekan tombol pada aktuator KNX, menaikkan MCB, atau menekan kontaktor untuk mengecek arah putaran motor."},{"g":"G. Marking scheme standar EI","t":"Switch actuator / dimmer actuator","a":"Aktuator KNX. Switch actuator untuk on/off beban (lampu, stopkontak). Dimmer actuator untuk mengatur terang lampu. C1, C2, dan seterusnya adalah nomor kanalnya."},{"g":"G. Marking scheme standar EI","t":"Input allocation","a":"Pembagian input smart relay. Contoh: selector manual ke I1, S11 ke I3, emergency stop ke I9, overload ke I11. Dicek dari layar smart relay."},{"g":"G. Marking scheme standar EI","t":"Operation – Function n","a":"Aspek otomatisasi (G1–G3). Setiap fungsi dari deskripsi soal diuji satu per satu: Ya jika bekerja persis sesuai instruksi."},{"g":"G. Marking scheme standar EI","t":"Interworking LOGO!/KNX","a":"Fungsi yang melibatkan smart relay dan KNX bersama-sama, misalnya input KNX menjalankan program di LOGO!."},{"g":"G. Marking scheme standar EI","t":"Centerline (garis sumbu)","a":"Garis tengah vertikal atau horizontal yang dipakai sebagai acuan ukur di gambar. Contoh aspek: \"H1 to vertical centerline ±2 mm\"."},{"g":"G. Marking scheme standar EI","t":"Plumb / level","a":"Tegak lurus (plumb) dan datar (level). Dicek dengan waterpass: gelembung harus di dalam atau tepat di garis, tidak boleh di luar."},{"g":"G. Marking scheme standar EI","t":"Wire-ways","a":"Semua jalur kabel: trunking, mini trunking, cable tray, conduit PVC, conduit logam, dan kabel yang diklem."},{"g":"G. Marking scheme standar EI","t":"Mini trunking","a":"Trunking PVC ukuran kecil, biasanya untuk ke saklar atau push button. Sambungan dan sudut 45° dinilai seperti trunking besar."},{"g":"G. Marking scheme standar EI","t":"Cable tray","a":"Rak atau baki kabel tempat kabel diletakkan dan diikat dengan cable tie. Dinilai kerapian, ikatan, dan lengkungannya."},{"g":"G. Marking scheme standar EI","t":"Premade joints","a":"Sambungan pabrikan (siku atau T jadi). Sambungan ini tidak ikut dinilai dalam mutu potongan trunking."},{"g":"G. Marking scheme standar EI","t":"Roll or movement","a":"Komponen atau jalur bergeser atau berputar ketika digoyang. Syarat \"securely installed\" berarti tidak ada roll atau movement sama sekali."},{"g":"G. Marking scheme standar EI","t":"A-side / B-side / Up-side","a":"Dinding booth atau cubicle lomba: sisi A, sisi B, dan bagian atas. Penempatan alat di setiap sisi dicek terhadap gambar."},{"g":"G. Marking scheme standar EI","t":"Jump over","a":"Lompatan atau offset conduit melewati rintangan, misalnya trunking. Jump over yang sama harus bentuknya sama persis."},{"g":"G. Marking scheme standar EI","t":"Distortion","a":"Penampang pipa penyok atau gepeng di lengkungan akibat bending yang salah. Mengurangi nilai J conduit."},{"g":"G. Marking scheme standar EI","t":"Bend radius","a":"Jari-jari lengkungan. Untuk nilai 3, semua lengkungan harus halus dengan radius identik dan sudut yang tepat."},{"g":"G. Marking scheme standar EI","t":"Clips evenly spaced","a":"Jarak klem atau saddle sama rata sepanjang jalur. Pembeda nilai 2 dan 3 untuk kabel yang diklem."},{"g":"G. Marking scheme standar EI","t":"Earth bonding","a":"Menyambungkan semua bagian logam (conduit logam, box, panel) ke titik pembumian (bonding point)."},{"g":"G. Marking scheme standar EI","t":"Loom / crossover","a":"Loom: berkas kabel yang dirapikan dan diikat. Crossover: kabel saling menyilang di dalam panel. Nilai 3 berarti tidak ada crossover dan semua kabel masuk lurus dan tegak ke switchgear."},{"g":"G. Marking scheme standar EI","t":"Kinks or twists","a":"Kabel tertekuk tajam atau terpuntir. Tidak boleh ada di cable tray."},{"g":"G. Marking scheme standar EI","t":"Bare copper","a":"Tembaga telanjang yang terlihat di terminal. Dicek dengan melihat tegak lurus (90°): tidak boleh ada tembaga terlihat, konduktor tidak rusak, dan kabel tidak goyang di terminal."},{"g":"G. Marking scheme standar EI","t":"Insulation resistance test","a":"Uji tahanan isolasi dengan insulation tester. Dinilai pemilihan alat dan prosedurnya, lalu nilai dan satuannya di report sheet (dua aspek terpisah)."},{"g":"G. Marking scheme standar EI","t":"Short circuit test","a":"Uji tidak ada hubung singkat antar penghantar sebelum diberi tegangan. Prosedur, nilai, dan satuannya harus benar."},{"g":"G. Marking scheme standar EI","t":"Earth continuity test","a":"Uji kontinuitas penghantar proteksi (PE) dari titik pembumian ke setiap bagian logam. Alat, prosedur, nilai, dan satuan dinilai."},{"g":"G. Marking scheme standar EI","t":"Value and unit","a":"Hasil ukur ditulis lengkap dengan satuannya, misalnya > 299 MΩ atau 0,12 Ω. Angka tanpa satuan dianggap salah."},{"g":"G. Marking scheme standar EI","t":"Below industry standard (0)","a":"Skor J 0: di bawah standar industri atau tidak dikerjakan."},{"g":"G. Marking scheme standar EI","t":"Meets industry standard (1)","a":"Skor J 1: memenuhi standar industri, tetapi masih ada kekurangan yang terlihat."},{"g":"G. Marking scheme standar EI","t":"Good practice (2)","a":"Skor J 2: standar industri dengan unsur praktik yang baik. Hanya ada kekurangan kecil."},{"g":"G. Marking scheme standar EI","t":"Excellent (3)","a":"Skor J 3: sangat baik dibanding standar industri, tanpa kekurangan. Deskripsi tiap skor untuk setiap aspek bisa dilihat dengan tombol ? di Assessment."},{"g":"G. Marking scheme standar EI","t":"Kode komponen di gambar","a":"Biasanya: H = lampu/indikator, O = stopkontak (outlet), PB = push button, A1/A2 = panel, M1 = motor, K1/K2 = kontaktor, F1… = ELCB/MCB, S = tombol/saklar, I = input smart relay, OL = overload, ES = emergency stop, POS = titik suplai. Selalu cek legenda di gambar test project."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"As per drawing / as per instructions","a":"Sesuai gambar / sesuai instruksi soal. Acuan utama semua aspek M."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Plus or minus 2 mm (±2 mm)","a":"Toleransi: boleh lebih atau kurang maksimal 2 mm dari ukuran di gambar."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Horizontal / vertical","a":"Mendatar / tegak. \"Horizontal and vertical centerline\" artinya diukur ke kedua garis sumbu."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Correct location","a":"Lokasi yang benar. \"Correct equipment in correct locations\" artinya alat yang tepat di tempat yang tepat."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Securely fitted / securely installed","a":"Terpasang kokoh: tidak goyang, bergeser, atau berputar."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Neat and tidy","a":"Rapi dan bersih. Sering dipakai pada deskripsi skor J."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Even / evenly spaced","a":"Rata, seragam / berjarak sama. Contoh: \"cable ties evenly spaced\" artinya jarak ikatan kabel sama rata."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Gaps / no gaps","a":"Celah / tanpa celah pada sambungan trunking."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Badly cut / excessive gaps","a":"Potongan buruk / celah berlebihan. Ciri skor J 0."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Lids / covers fitted","a":"Tutup trunking atau box terpasang dengan benar."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Straight runs","a":"Jalur kabel atau pipa yang lurus."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Bends / angles","a":"Lengkungan / sudut pada conduit, trunking, atau kabel."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Smooth / identical / matching","a":"Halus / sama persis / serasi. Syarat skor J 3 untuk conduit."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Majority of / all of","a":"Sebagian besar / semuanya. Pembeda skor J 1–2 dan skor 3."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Minor / some / very few","a":"Kecil / beberapa / sangat sedikit. Menunjukkan tingkat kekurangan pada deskripsi skor J."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Termination to trunking or boxes","a":"Ujung conduit yang masuk ke trunking atau box harus rapi dan memakai aksesori yang benar."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Securely terminated","a":"Kabel terjepit kuat di terminal, tidak bisa dicabut atau digoyang."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Labelled correctly","a":"Diberi label dengan benar. Semua alat harus berlabel setelah commissioning."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Feed / main switch","a":"Feed: suplai atau pengisi daya untuk suatu rangkaian (MCB pengisi). Main switch: saklar utama, biasanya ELCB."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Motor protection","a":"Proteksi motor, misalnya MCB motor atau overload."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Running direction / forward / backward","a":"Arah putaran motor / maju / mundur."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Confirmed by 2 experts","a":"Disetujui minimal 2 juri sebelum nilai 0 diberikan."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Observed","a":"Terlihat atau teramati langsung oleh juri saat pekerjaan berlangsung."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Yes / no","a":"Ya / tidak. Jenis isian aspek Measurement (M)."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Requirement","a":"Syarat yang harus dipenuhi agar aspek M mendapat nilai penuh."},{"g":"H. Kosakata bahasa Inggris di marking scheme","t":"Below / meets / excellent","a":"Di bawah / memenuhi / jauh melampaui standar industri. Kata kunci skala J 0–3."}]}$cfg$::jsonb
where not exists (select 1 from public.seasons);

insert into public.competitors (season_id, name, kelas, peran, sort)
select s.id, x.name, x.kelas, 'Peserta', x.sort
from public.seasons s,
     (values ('Siswa kelas XI','XI',1), ('Siswa kelas X','X',2)) as x(name,kelas,sort)
where s.name = 'LKS EI 2026–2027'
  and not exists (select 1 from public.competitors c where c.season_id = s.id);

-- Selesai. Lanjutkan ke langkah berikutnya di README.

-- ===== Log harian & aktivitas (sama dengan update-log.sql) =====
-- 1. Izinkan jenis data baru 'log' (log kegiatan harian asisten)
alter table public.records drop constraint if exists records_kind_check;
alter table public.records add constraint records_kind_check
  check (kind in ('mark','lock','done','gate','journal','log'));

-- 2. Tabel aktivitas otomatis: siapa melakukan apa, kapan
create table if not exists public.activity (
  id bigserial primary key,
  season_id uuid references public.seasons(id) on delete cascade,
  rec_id text,
  kind text,
  ref text,
  competitor_id uuid,
  action text,
  n int not null default 1,
  user_id uuid,
  first_at timestamptz not null default now(),
  at timestamptz not null default now()
);
create index if not exists activity_season_at_idx on public.activity(season_id, at desc);
alter table public.activity enable row level security;
drop policy if exists "activity read" on public.activity;
create policy "activity read" on public.activity for select to authenticated using (true);

-- 3. Catat otomatis setiap kali data latihan disimpan atau dihapus.
--    Simpan berulang pada data yang sama dalam 15 menit digabung jadi satu baris.
create or replace function public.log_activity() returns trigger
language plpgsql security definer set search_path = public as $$
declare r record; u uuid := auth.uid(); act text; last_id bigint;
begin
  if u is null then return null; end if;
  if tg_op = 'DELETE' then
    r := old; act := 'hapus';
    if not exists (select 1 from public.seasons where id = old.season_id) then return null; end if;
    if old.competitor_id is not null and not exists (select 1 from public.competitors where id = old.competitor_id) then return null; end if;
  else
    r := new; act := case when tg_op = 'INSERT' then 'buat' else 'ubah' end;
  end if;
  if act <> 'hapus' then
    select id into last_id from public.activity
      where rec_id = r.id and user_id = u and action <> 'hapus' and at > now() - interval '15 minutes'
      order by at desc limit 1;
  end if;
  if last_id is not null then
    update public.activity set at = now(), n = n + 1 where id = last_id;
  else
    insert into public.activity (season_id, rec_id, kind, ref, competitor_id, action, user_id)
    values (r.season_id, r.id, r.kind, r.ref, r.competitor_id, act, u);
  end if;
  return null;
end $$;
drop trigger if exists records_activity on public.records;
create trigger records_activity after insert or update or delete on public.records
  for each row execute function public.log_activity();

-- 4. Kolom updated_by selalu berisi orang yang terakhir menyimpan
create or replace function public.stamp_record() returns trigger
language plpgsql as $$
begin new.updated_by := coalesce(auth.uid(), new.updated_by); return new; end $$;
drop trigger if exists records_stamp on public.records;
create trigger records_stamp before insert or update on public.records
  for each row execute function public.stamp_record();

-- ===== Foto & laporan TO (sama dengan update-foto.sql) =====
-- 1. Izinkan jenis data 'photo' (data foto per TO/bagian penilaian)
alter table public.records drop constraint if exists records_kind_check;
alter table public.records add constraint records_kind_check
  check (kind in ('mark','lock','done','gate','journal','log','photo','harian'));

-- 2. Tempat penyimpanan foto (privat, maks 5 MB per foto, hanya gambar)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('tis-foto', 'tis-foto', false, 10485760, array['image/jpeg','image/png','image/webp','application/pdf'])
on conflict (id) do update set file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- 3. Hak akses: semua pengguna yang masuk boleh melihat; admin & juri boleh unggah/hapus
drop policy if exists "tis foto read" on storage.objects;
create policy "tis foto read" on storage.objects for select to authenticated
  using (bucket_id = 'tis-foto');
drop policy if exists "tis foto insert" on storage.objects;
create policy "tis foto insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'tis-foto' and public.my_role() in ('admin','juri'));
drop policy if exists "tis foto delete" on storage.objects;
create policy "tis foto delete" on storage.objects for delete to authenticated
  using (bucket_id = 'tis-foto' and public.my_role() in ('admin','juri'));
